// 9 Nov (Alex): in-game HUD, style D. Neutral dark steel + thin gold (ChatGPT art, assets/hud-d), small accents in the class colour
// (imperial blue / draconic red / arcana purple, pre-tinted at build time). It re-skins the client HUD the engine builds
// (status, target, run panel, hotbar, menu, XP strip, chat, windows, minimap, buffs, cast bar, boss countdown) with CSS and a few
// image swaps; it never touches the game logic. Cards stay as they are. Without l2-hud.js the client look shows.
(() => {
const H = window.L2HUD; if (!H) return;
const I = H.img, url = n => `url(${I[n]})`;
// ---- class -> skin (same map as the town and lobby), read from the save the hub wrote
let skin = 'imperial';
try {
  const m = location.hash.match(/hub=([^&]+)/), hub = m ? JSON.parse(decodeURIComponent(escape(atob(m[1])))) : null;   // the run state the town sends (same parse as the engine)
  if (hub && hub.cls && H.skin[hub.cls]) skin = H.skin[hub.cls];
  else {
  const ch = JSON.parse(localStorage.getItem('l2chars') || 'null'), sv = ch && ch.cur ? JSON.parse(localStorage.getItem('l2play:' + ch.cur) || 'null') : null;
  const cls = (sv && sv.cls) || (ch && (ch.list || []).find(c => c.name === ch.cur) || {}).cls;
  if (cls && H.skin[cls]) skin = H.skin[cls];
  }
} catch (e) {}
const T = n => url(n + '_' + skin);   // tinted accent pieces
const ACC = { imperial: '#5b94ec', draconic: '#e0583c', arcana: '#b276ee' }[skin];
// ---- target ring under the feet (the engine tints its decal gold)
if (window.ASSETS && ASSETS.ui && H.ring) ASSETS.ui.target_decal = H.ring;

const css = `
:root{--hz:1;--acc:${ACC}}
#status,#svstat,#target,#runtimer,#minimap,#leaverun,#bottom,#menu,#chat,#buffs,#autoplay,.win,#castbar,#bosscd,#bossbar{zoom:var(--hz)}
.l2b{background:none!important;border-style:solid!important;border-color:transparent!important;border-width:0 10px!important;border-image:${url('tab_off')} 0 16 fill / 0 10px stretch!important;color:#f3e2b0!important}.l2b:hover{border-image-source:${url('tab_on')}!important}
#sysbar{zoom:var(--hz)}
/* small frames: status, target, run panel */
.sbg{border-width:10px!important;border-image:${url('frame_hud')} 24 fill / 12px stretch!important}
#status .sbg::after,#runtimer .sbg::after{content:'';position:absolute;right:-14px;top:-14px;width:16px;height:16px;background:${T('gem')} 0 0/100% 100%}#runtimer .sbg::after{right:auto;left:-14px}
.lvb{background:${url('lvl_badge')} center/22px 22px no-repeat!important}.lvb span{color:#f3e2b0!important;top:5px!important}
.unm{color:#f3ead2}
/* bars */
.g .bg b,.g .bg i,.g .fg b,.g .fg i,.tg .bg b,.tg .bg i,.tg .fg b,.tg .fg i{display:none!important}
.g .bg,.g .fg{box-sizing:border-box;border-style:solid;border-color:transparent;border-width:0 5px}
.g .bg{border-image:${url('bar_track')} 0 10 fill / 0 5px stretch}
.g .fg{border-image:${url('bar_hp')} 0 10 fill / 0 5px stretch}
.g[data-k=CP] .fg{border-image-source:${url('bar_cp')}}.g[data-k=MP] .fg{border-image-source:${url('bar_mp')}}.g[data-k=EXP] .fg{border-image-source:${T('bar_xp')}}
.tg .bg,.tg .fg{box-sizing:border-box;border-style:solid;border-color:transparent;border-width:0 3px}
.tg .bg{right:0;border-image:${url('bar_thin_track')} 0 6 fill / 0 3px stretch}.tg .fg{border-image:${url('bar_thin_hp')} 0 6 fill / 0 3px stretch}
/* hotbar */
.wsv::before{border-width:10px!important;border-image:${url('frame_hud')} 24 fill / 12px stretch!important}
#hotbar .hx{visibility:hidden}
#hotbar .slot::before{content:'';position:absolute;left:-2px;top:-2px;width:36px;height:36px;background:${url('slot')} 0 0/36px 36px;pointer-events:none;z-index:2}
#hotbar .slot:hover::before{background-image:${url('slot_hover')}}
#hotbar .slot.auto::before{background-image:${T('slot_sel')}}
#hotbar .slot .fr{display:none!important}
#hotbar .slot kbd{z-index:3}
.hpage,.hlab{color:#f3e2b0}
/* side buttons */
.hb.dk{background-size:100% 100%!important;background-repeat:no-repeat!important}
/* soulshot / spiritshot strip */
#autoshot .hx{visibility:hidden}
#autoshot .hgrp::before{content:'';position:absolute;inset:-4px;border:10px solid transparent;border-image:${url('frame_hud')} 24 fill / 10px stretch;z-index:-1}
#autoshot .hgrp{isolation:isolate}
.shot::before{content:'';position:absolute;left:-1px;top:-1px;width:28px;height:28px;background:${url('slot')} 0 0/28px 28px;pointer-events:none;z-index:2}
.shot.on::before{background-image:${T('slot_sel')}}
/* menu */
#menu{background:none!important}
#menu::before{content:'';position:absolute;inset:0;border:12px solid transparent;border-image:${url('frame_hud')} 24 fill / 12px stretch}
.mb{background:${url('btn_sq')} 0 0/100% 100% no-repeat!important}.mb:hover{background-image:${url('btn_sq_hover')}!important}.mb:active{background-image:${url('btn_sq_down')}!important}
.mb img{width:25px!important;height:25px!important;margin:6px!important}.mb.dis img{filter:grayscale(1) brightness(.6)}
/* XP strip */
#sysbar::before{border-width:0 32px!important;border-image:${url('strip_bottom')} 0 64 fill / 0 32px stretch!important}
#sysbar .xg{border:0!important;box-shadow:none!important;background:none!important;border-radius:0!important;border-style:solid!important;border-color:transparent!important;border-width:0 5px!important;border-image:${url('bar_track')} 0 10 fill / 0 5px stretch!important}
#sysbar .tr{background:none!important;left:-4px!important;right:-4px!important;top:0!important;bottom:0!important}
#sysbar .fl{box-sizing:border-box;background:none!important;border-style:solid;border-color:transparent;border-width:0 5px;border-image:${T('bar_xp')} 0 10 fill / 0 5px stretch}
#sysbar .xd{opacity:.5}
/* chat */
#chat .cx{visibility:hidden}
#chat::before{content:'';position:absolute;left:0;top:-6px;right:0;bottom:0;border:12px solid transparent;border-image:${url('frame_hud')} 24 fill / 12px stretch;pointer-events:none}
.ctab{box-sizing:border-box;background:none!important;border-style:solid;border-color:transparent;border-width:0 8px;border-image:${url('tab_off')} 0 16 fill / 0 8px stretch;line-height:22px!important}
.ctab.on{border-image-source:${url('tab_on')};color:#fff3d6}.ctab.dis{border-image-source:${url('tab_dis')};filter:none}
/* windows */
.wbg{border-image:${url('frame_win')} 40 fill / 20px / 8px stretch!important}
.win .wt{isolation:isolate}
.win .wt::before{content:'';position:absolute;left:8px;right:8px;top:-4px;height:30px;border-style:solid;border-color:transparent;border-width:0 32px;border-image:${url('win_title')} 0 64 fill / 0 32px stretch;z-index:-1;pointer-events:none}
.win .wt span{font:13px Georgia,serif;color:#f3e2b0;letter-spacing:.5px}
.wt .x{background:${url('b_close')} center/100% 100% no-repeat!important;width:18px!important;height:18px!important;top:3px!important;right:6px!important}.wt .x:active{background-image:${url('b_close_down')}!important}
.tab{border-image:${url('tab_off')} 0 16 fill / 0 8px stretch!important;border-width:0 8px!important}.tab.on{border-image-source:${url('tab_on')}!important}
.is{background:${url('slot_item')} center/100% 100% no-repeat,rgba(10,9,8,.55)!important}
.gbox{border-image:${url('frame_hud')} 24 fill / 8px stretch!important;border-width:6px!important}
/* buffs */
#buffs::before{display:none!important}
#buffs .bi{background:${url('slot')} 0 0/26px 26px no-repeat!important}#buffs .bi img{z-index:-1}
/* minimap: round, painted ring */
#minimap{border:0!important;border-image:none!important;box-shadow:none!important;border-radius:50%;padding:4px!important}
#minimap canvas{border-radius:50%}
#minimap::after{content:'';position:absolute;left:-4px;top:-4px;width:192px;height:192px;background:${T('minimap_ring')} 0 0/100% 100% no-repeat;pointer-events:none}
#minimap .mm-n{font-size:0!important;width:14px;height:14px;top:-2px!important;background:${url('minimap_north')} 0 0/100% 100%;z-index:2}
#minimap .mm-z{right:14px!important;bottom:14px!important;z-index:2}
#mmplus{background:${url('b_plus')} 0 0/100% 100%!important}#mmplus:active{background-image:${url('b_plus_down')}!important}
#mmminus{background:${url('b_minus')} 0 0/100% 100%!important}#mmminus:active{background-image:${url('b_minus_down')}!important}
/* cast bar (trials) and boss countdown */
#castbar .cb-b{height:16px!important;background:none!important;border:0!important;border-radius:0!important;padding:3px 8px;box-sizing:border-box;border-style:solid!important;border-color:transparent!important;border-width:0 12px!important;border-image:${url('cast_bar')} 0 24 fill / 0 12px stretch!important}
#castbar .cb-f{border-radius:2px}
#bosscd{padding:0;background:none}   /* 10 Nov: the banner frames the heading only; the number sits below it, clear of the rim */
#bosscd small{display:inline-block;min-width:300px;padding:14px 64px 15px;background:${url('boss_banner')} center/100% 100% no-repeat;color:#f3e2b0}
#bosscd b{margin-top:8px}
/* boss HP bar (10 Nov) */
#bossbar .bb-t{height:22px;background:none;border:0;box-shadow:none;border-style:solid;border-color:transparent;border-width:0 14px;border-image:${url('boss_bar')} 0 28 fill / 0 14px stretch}
#bossbar .bb-f{top:4px;bottom:4px;background:linear-gradient(#c8382a,#6e120a);border-radius:2px}
#bossbar .bb-p{font:11px/22px Tahoma,sans-serif;color:#f3ead2}
#bossbar .bb-n{color:#f3e2b0}
/* auto-play wheel */
#autoplay #apFrame{visibility:hidden}
#autoplay::before{content:'';position:absolute;left:-6px;top:18px;width:150px;height:150px;background:${url('auto_wheel')} 0 0/100% 100% no-repeat;pointer-events:none;opacity:.95}
`;
const st = document.createElement('style'); st.id = 'hud-d'; st.textContent = css; document.head.appendChild(st);
// ---- scale: the client HUD is drawn at native pixel size; grow it with the screen (1x at 900 px high, steps of 0.25, up to 2x)
const fit = () => document.documentElement.style.setProperty('--hz', Math.min(2, Math.max(1, Math.round(innerHeight / 900 * 4) / 4)));
fit(); addEventListener('resize', fit);
// ---- image swaps the CSS can't do: menu icons, hotbar side buttons, auto-use state on the hotbar
const MENU = ['ico_char', 'ico_inv', 'ico_action', 'ico_skill', 'ico_quest', 'ico_clan', 'ico_map', 'ico_all'];
const SIDE = { 'Next page': 'b_up', 'Previous page': 'b_down', Expand: 'b_expand', Rotate: 'b_rotate', Lock: 'b_lock', 'Font size': 'b_plus', 'Chat filter': 'b_expand' };
function swap() {
  document.querySelectorAll('#menu .mb img').forEach((im, i) => { if (MENU[i] && !im.dataset.d) { im.dataset.d = 1; im.src = I[MENU[i]]; } });
  document.querySelectorAll('#hotbar .hb[title], #chat .hb[title]').forEach(b => { const n = SIDE[b.title]; if (n && !b.classList.contains('dk')) { b.classList.add('dk'); b.style.setProperty('--n', url(n)); b.style.setProperty('--o', url(n)); b.style.setProperty('--d', url(n + '_down')); } });
  document.querySelectorAll('#hotbar .slot.set').forEach(s => { const t = s.querySelector('.tog'); s.classList.toggle('auto', !!(t && t.style.display && t.style.display !== 'none')); });
}
let q = 0; new MutationObserver(() => { if (!q) q = requestAnimationFrame(() => { q = 0; swap(); }); }).observe(document.body, { childList: true, subtree: true });
setInterval(swap, 400);   // auto-use on/off shows as a style change on .tog: polled, not observed (nameplates and damage text change styles every frame)
})();
